namespace mdemangler.datatype.modifier;

using mdemangler;
using mdemangler;

/**
 * This class represents a "pointer" data type within a Microsoft mangled symbol.
 */
public class MDPointerType : MDModifierType {

	public MDPointerType(MDMang dmang, bool isHighest, bool isConst, bool isVolatile) : base(dmang)
    {
		if (isHighest) {
			setConst(isConst);
			setVolatile(isVolatile);
		}
		else {
			setConst(false);
			setVolatile(false);
		}
		cvMod.setPointerType();
	}

	/* @Override */
	protected void parseInternal()
    {
		base.parseInternal();
	}

	/* @Override */
	public void insertCVMod(StringBuilder builder) {
		if (cvMod.isFunction()) {
			StringBuilder cvBuilder = new StringBuilder();
			cvMod.insert(cvBuilder);
			dmang.insertString(builder, cvBuilder.toString());
		}
		else {
			cvMod.insert(builder);
		}
		// Following is to clean the Based5 "bug" if seen.  See comments in MDBasedAttribute.
		dmang.cleanOutput(builder);
	}
}
